def orf_from(s, i):
    """translate from ATG at 0-based index i until stop; return (prot_list, ncodons_incl_stop)."""
    prot = []
    j = i
    while j+3 <= len(s):
        a = codon_table[s[j:j+3]]
        prot.append(a)
        if a == '*':
            return prot, True
        j += 3
    return prot, False

